import hashlib, json, re
from datetime import datetime, timezone
from pathlib import Path

source = Path('products/services/boamp-data-quality-pilot/official-query.json')
raw = source.read_bytes()
package = json.loads(raw)
cutoff = datetime(2026, 11, 21, tzinfo=timezone.utc)
terms = re.compile(r'qualit[ée]\s+des\s+donn[ée]es|contr[ôo]les?\s+de\s+coh[ée]rence|d[ée]doublonnage|rapprochement\s+des\s+donn[ée]es', re.I)

def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from strings(item)

records = []
for record in package['results']:
    deadline = record.get('datelimitereponse')
    try:
        parsed = datetime.fromisoformat(deadline.replace('Z', '+00:00'))
        future = parsed > cutoff if parsed.tzinfo else None
    except (AttributeError, ValueError):
        future = None
    matches = {}
    for field in ('objet', 'donnees', 'criteres'):
        text = '\n'.join(strings(record.get(field)))
        phrases = sorted({match.group() for match in terms.finditer(text)})
        if phrases:
            matches[field] = phrases
    records.append({'idweb': record.get('idweb'), 'title': record.get('objet'), 'notice_url': record.get('url_avis'), 'notice_nature': record.get('nature'), 'deadline_as_returned': deadline, 'deadline_after_cutoff': future, 'matched_phrases_by_field': matches})
result = {'source': str(source), 'source_sha256': hashlib.sha256(raw).hexdigest(), 'cutoff': cutoff.isoformat(), 'returned_count': len(records), 'records': records, 'candidate_ids': [item['idweb'] for item in records if item['deadline_after_cutoff'] and item['matched_phrases_by_field']], 'limit': 'Local literal screen of the saved response. A phrase does not establish paid scope, active status, acceptance criteria or submission eligibility. No match does not establish that the API applied its filter or that the market lacks relevant notices.'}
output = source.with_name('captured-scope-screen.json')
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps(json.loads(output.read_text(encoding='utf-8')), ensure_ascii=False))
